'use strict';
(() => {
  const course = window.COURSE;
  const main = document.querySelector('#main');
  if (!course || !Array.isArray(course.modules)) { main.innerHTML = '<h1>Não foi possível abrir a trilha.</h1><p>Recarregue a página para tentar novamente.</p>'; return; }
  const KEY = 'ui-mobile-study-v2';
  const lessons = course.modules.flatMap((m, mi) => m.lessons.map((l, li) => ({...l,module:m,moduleIndex:mi,lessonIndex:li})));
  const byId = new Map(lessons.map(l=>[l.id,l]));
  const check = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>';
  const arrow = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>';
  const external = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14 4h6v6m0-6-9 9M11 5H5v14h14v-6"/></svg>';
  const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normalize = s => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const plain = s => String(s).replace(/<[^>]*>/g,' ');
  const pct = (done,total) => total ? Math.round(done/total*100) : 0;
  const legacyRoutes={'pesquisa-hipotese-teste':'ux-ui-problema-objetivos','teste-usabilidade-evidencia':'acessibilidade-plano-verificacao'};
  const state = {completed:[],lastLesson:null,positions:{},archived:{completed:[],positions:{},lastLesson:null}};
  let storageWorks = true, activeRoute = '', scrollTimer, importMessage = '', resumeRequested = false;
  function cleanState(raw) {
    if(!raw || typeof raw!=='object' || Array.isArray(raw)) throw new Error('O arquivo não contém um progresso válido.');
    if(raw.schemaVersion !== undefined && raw.schemaVersion !== 2) throw new Error('A versão do arquivo não é compatível com esta trilha.');
    if(raw.course !== undefined && raw.course !== 'ui-mobile') throw new Error('Este arquivo pertence a outra trilha.');
    if(!Array.isArray(raw.completed)) throw new Error('Não encontramos a lista de lições estudadas.');
    const completed=[...new Set(raw.completed.filter(x=>typeof x==='string' && byId.has(x)))];
    const positions={};
    if(raw.positions && typeof raw.positions==='object' && !Array.isArray(raw.positions)) for(const [id,y] of Object.entries(raw.positions)) if(byId.has(id) && Number.isFinite(y) && y>=0 && y<1e7) positions[id]=y;
    const archived={completed:[],positions:{},lastLesson:null};
    archived.completed=[...new Set([...(raw.archived?.completed||[]),...raw.completed].filter(id=>Object.hasOwn(legacyRoutes,id)&&!byId.has(id)))];
    for(const [id,y] of Object.entries({...raw.archived?.positions,...raw.positions})) if(Object.hasOwn(legacyRoutes,id)&&!byId.has(id)&&Number.isFinite(y)&&y>=0&&y<1e7)archived.positions[id]=y;
    const previous=raw.archived?.lastLesson||raw.lastLesson;
    if(Object.hasOwn(legacyRoutes,previous)&&!byId.has(previous))archived.lastLesson=previous;
    return {completed,lastLesson:byId.has(raw.lastLesson)?raw.lastLesson:null,positions,archived};
  }
  try { const stored=localStorage.getItem(KEY); if(stored) Object.assign(state,cleanState(JSON.parse(stored))); } catch(e) { if(e.name==='SecurityError') storageWorks=false; }
  function persist() { try { localStorage.setItem(KEY,JSON.stringify({schemaVersion:2,course:'ui-mobile',...state,updatedAt:new Date().toISOString()})); } catch(e) {storageWorks=false;} document.querySelector('#storage-warning').hidden=storageWorks; }
  const done = id => state.completed.includes(id);
  const indicator = id => `<span class="lesson-indicator${done(id)?' is-done':''}" aria-hidden="true">${done(id)?check:''}</span>`;
  function markButton(id) { return `<button class="button ${done(id)?'done':''}" data-complete="${esc(id)}" aria-pressed="${done(id)}">${done(id)?check:''}${done(id)?'Lição estudada':'Marcar como estudada'}</button>`; }
  const footer = () => `<footer class="page-footer">Material de estudo autoral em português. Referências externas pertencem aos respectivos autores e organizações. Revisado em outubro de 2026.<br>Rota é um aplicativo fictício usado nos exemplos. As referências indicam quando uma recomendação depende da plataforma.<br>Sem conta e sem analytics próprios. O progresso é salvo apenas neste navegador.</footer>`;
  function updateProgress() {
    const total=state.completed.length, percent=pct(total,lessons.length);
    document.querySelector('#total-label').textContent=`${percent}% · ${total}/${lessons.length} lições`;
    document.querySelector('#total-bar').style.width=percent+'%';
    const resume=state.lastLesson || lessons.find(l=>!done(l.id))?.id || lessons[0]?.id;
    document.querySelector('#continue-top').href='#'+resume;
    document.querySelectorAll('[data-complete]').forEach(el=>{const id=el.dataset.complete;el.classList.toggle('done',done(id));el.setAttribute('aria-pressed',String(done(id)));el.innerHTML=(done(id)?check:'')+(done(id)?'Lição estudada':'Marcar como estudada');});
    renderNav(document.querySelector('#course-search').value);
  }
  const searchable = new Map(lessons.map(l=>[l.id,normalize([l.title,l.summary,l.module.title,...l.sections.map(s=>s.title+' '+plain(s.body)),...l.examples.map(e=>e.title+' '+plain(e.analysis))].join(' '))]));
  function renderNav(query='') {
    const terms=normalize(query).trim().split(/\s+/).filter(Boolean);
    let matchCount=0;
    let html=`<a class="nav-overview" href="#inicio" ${activeRoute==='inicio'?'aria-current="page"':''}>Visão geral da trilha</a>`;
    course.modules.forEach((m,mi)=>{
      const found=m.lessons.filter(l=>terms.every(t=>searchable.get(l.id)?.includes(t)));
      if(!found.length) return;
      matchCount+=found.length;
      const count=m.lessons.filter(l=>done(l.id)).length;
      html+=`<div class="nav-group"><div class="nav-group-head"><span>${String(mi+1).padStart(2,'0')} · ${esc(m.title)}</span><span class="nav-group-percent">${pct(count,m.lessons.length)}%</span></div><ol class="nav-lessons">${found.map(l=>`<li><a href="#${esc(l.id)}" ${activeRoute===l.id?'aria-current="page"':''}>${indicator(l.id)}<span>${esc(l.title)}${done(l.id)?'<span class="sr-only">, estudada</span>':''}</span></a></li>`).join('')}</ol></div>`;
    });
    document.querySelector('#course-nav').innerHTML=html;
    document.querySelector('#search-status').textContent=terms.length?`${matchCount} ${matchCount===1?'lição encontrada':'lições encontradas'}`:'';
    document.querySelectorAll('.utility-nav a').forEach(a=>{if(a.hash.slice(1)===activeRoute)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  }
  function moduleContract(m,includeLessons=false) {
    return `<section class="module-contract"><h4>Objetivo</h4><p>${esc(m.objective||m.description)}</p>${m.rationale?`<p class="module-rationale"><strong>Por que este assunto vem aqui:</strong> ${esc(m.rationale)}</p>`:''}${includeLessons?`<h4>O que estudar</h4><ol class="module-lessons">${m.lessons.map(l=>`<li><a href="#${esc(l.id)}">${indicator(l.id)}<span>${esc(l.title)}</span></a></li>`).join('')}</ol>`:''}<h4>Para saber mais</h4><ul class="module-references">${(m.references||m.sources||[]).map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}<span class="sr-only"> (abre em nova aba)</span></a></li>`).join('')}</ul></section>`;
  }
  function renderOverview() {
    const resume=state.lastLesson||lessons.find(l=>!done(l.id))?.id||lessons[0].id;
    return `<div class="overview"><section class="hero"><div class="hero-kicker"><span class="eyebrow">Fundamentos de UI · design de interfaces</span><span class="tag">Foco mobile</span></div><h1>Fundamentos de UI<br>para iniciantes.</h1><p class="intro">Entenda como organizar telas, escolher tipografia e cores e cuidar dos detalhes da interface. Antes do desenho, veja como a UX ajuda a entender o problema, o público e os requisitos.</p><div class="button-row"><a class="button primary" data-resume="true" href="#${esc(resume)}">${state.lastLesson?'Continuar de onde parei':'Começar pelo problema'} ${arrow}</a><a class="button" href="#biblioteca">Consultar referências</a></div><div class="stat-line"><div><b>${course.modules.length}</b><span>blocos no percurso</span></div><div><b>${lessons.length}</b><span>lições explicadas</span></div><div><b>${state.completed.length}/${lessons.length}</b><span>lições estudadas</span></div></div></section><section class="study-guide"><div><h2>Um exemplo para acompanhar as explicações</h2><p>Rota é um aplicativo fictício para descobrir visitas culturais e organizar um passeio. Ele aparece nos exemplos para mostrar como cada conceito funciona em uma interface. Não é um projeto que você precisa entregar.</p><p>As figuras mostram comparações, detalhes ampliados e telas comentadas. Cada legenda explica o que mudou e por que isso faz diferença.</p></div><div><h2>Como o conteúdo está organizado</h2><ol><li>O que é: uma definição simples do conceito.</li><li>Para que serve: qual problema ele ajuda a resolver.</li><li>Onde usar: exemplos de situações e telas.</li><li>Boas práticas: cuidados para usar o conceito com clareza.</li></ol></div></section><section class="learning-roadmap" aria-labelledby="roadmap-heading"><h2 id="roadmap-heading">Os assuntos, na ordem de leitura.</h2><p>Comece pelo papel da UX antes da tela. Em seguida, avance pelos fundamentos visuais. Você também pode abrir qualquer assunto pelo índice.</p><ol class="craft-roadmap">${course.modules.map((m,i)=>{const n=m.lessons.filter(l=>done(l.id)).length;return `<li><a href="#inicio--module-${esc(m.id)}"><span class="roadmap-number">${String(i+1).padStart(2,'0')}</span><strong>${esc(m.title)}</strong><span>${n}/${m.lessons.length} estudadas · ${pct(n,m.lessons.length)}%</span><span class="roadmap-track" aria-hidden="true"><i style="width:${pct(n,m.lessons.length)}%"></i></span></a></li>`;}).join('')}</ol></section><div class="section-heading"><h2>O que você encontra em cada bloco</h2><p>Uma explicação do assunto, as lições em ordem e referências para saber mais.</p></div><div class="module-grid">${course.modules.map((m,i)=>`<section class="module-card" id="inicio--module-${esc(m.id)}"><div class="module-card-number">Bloco ${String(i+1).padStart(2,'0')}</div><h3>${esc(m.title)}</h3>${moduleContract(m,true)}<div class="module-card-footer"><span>${m.lessons.length} lições</span><span>${pct(m.lessons.filter(l=>done(l.id)).length,m.lessons.length)}% estudado</span></div></section>`).join('')}</div><p class="privacy-note">O progresso fica neste navegador. Você pode <a href="#progresso">exportar e importar uma cópia</a>. Suas marcações anteriores continuam salvas.</p>${footer()}</div>`;
  }
  const renderBook = b => `<li><cite>${esc(b.title)}</cite><span>${esc(b.authors)}${b.edition?` · ${esc(b.edition)}`:''}</span><small>${esc(b.pages)}${b.note?` · ${esc(b.note)}`:''}</small>${b.url?`<a href="${esc(b.url)}" target="_blank" rel="noopener noreferrer">Informações da obra</a>`:''}</li>`;
  // Each figure isolates a visual decision; the full Rota composition remains available below it.
  const craftPanel=(label,body,caption,cls='')=>`<section class="craft-panel ${cls}"><h4>${label}</h4><div class="craft-specimen">${body}</div><p class="craft-caption">${caption}</p></section>`;
  const craftCard=(cls='')=>`<div class="craft-visit ${cls}"><span class="craft-overline">EXPOSIÇÃO · CENTRO</span><strong>Forma &amp; luz</strong><p>Galeria Horizonte</p><p>Sábado, 24 out · 14h</p><span class="craft-action">Salvar plano</span></div>`;
  const craftList=(cls='')=>`<div class="craft-list ${cls}">${[['Forma &amp; luz','Galeria Horizonte','14h'],['Objetos do tempo','Casa das Artes','15h30'],['Cidade em traços','Ateliê Central','17h']].map(([a,b,c])=>`<div><span><strong>${a}</strong><small>${b}</small></span><b>${c}</b></div>`).join('')}</div>`;
  function craftFigure(l) {
    const id=l.id;
    let title='',caption='',html='';
    if(id==='ux-ui-problema-objetivos'){
      title='Antes da tela: problema, pessoas e requisitos';
      html=craftPanel('1 · Problema','<p>Quem quer visitar uma exposição precisa descobrir o horário e saber se ela cabe no seu dia.</p>','UX ajuda a entender essa dificuldade antes de escolher a aparência da tela.')+craftPanel('2 · Público e contexto','<p>A pessoa está no celular, no caminho para o Centro, e tem apenas a tarde livre.</p>','Conhecer o público ajuda a decidir quais informações precisam estar fáceis de encontrar.')+craftPanel('3 · Requisitos','<p>A tela precisa mostrar nome, local, data, horário e uma forma de salvar a visita.</p>','Requisitos são as informações, funções e condições que a solução precisa atender.')+craftPanel('4 · Interface',craftCard(),'UI organiza esses elementos: nome em destaque, dados legíveis e botão de salvar fácil de identificar.');
      caption='UX trata da experiência de uso: o problema, as pessoas e como a solução funciona. UI trata da interface: como informações e controles aparecem na tela. As duas áreas trabalham juntas.';
    } else if(id==='hierarquia-visual'){
      title='Mesmos dados. Outra ordem de leitura.';html=craftPanel('Antes · tudo com o mesmo destaque',craftCard('craft-flat'),'Título, local e ação disputam o mesmo nível.')+craftPanel('Depois · destaques diferentes',craftCard(),'O título mostra o nome da exposição. O texto menor informa local e data. O botão mostra o próximo passo.');caption='Compare a primeira informação que encontra em cada versão. Tamanho, peso, espaçamento e contraste da ação mudam; os dados e a ordem permanecem iguais.';
    } else if(['composicao-grid-espacamento','grid-responsividade-densidade','whitespace-relacoes'].includes(id)) {
      title=id==='whitespace-relacoes'?'O intervalo também agrupa':'A medida precisa apontar para o espaço';
      html=craftPanel('Recorte anotado',`<div class="craft-measure"><div class="craft-measure-margin">↔ 24px · margem</div><div class="craft-grid"><div class="craft-measured-field"><span>Exposição</span><i class="craft-dimension">↕ 8px · rótulo → valor</i><strong>Forma &amp; luz</strong></div><div class="craft-gutter">↕ 24px · entre grupos</div><div class="craft-grid-pair"><div><span>Dia</span><strong>24 out</strong></div><i>↔<br>16px</i><div><span>Hora</span><strong>14h</strong></div></div></div></div>`,'As marcações mostram a medida de cada espaço: margem, espaço interno e distância entre grupos. A grade de fundo tem passo de 8 CSSpx; as marcações são ampliadas para facilitar a leitura.');caption='Neste exemplo, os espaços são de 8, 16 e 24 pixels de referência da web (CSSpx). Outros projetos podem usar medidas diferentes. As marcações não estão em escala. Espaços curtos aproximam informações relacionadas; espaços maiores separam grupos. A largura das colunas se adapta ao conteúdo disponível.';
    } else if(id==='densidade-ritmo-escaneabilidade'||id==='listas-cards') {
      title='Três ritmos, os mesmos três passeios';html=['compact','regular','airy'].map((c,i)=>craftPanel(['Compacta · 8px','Equilibrada · 16px','Arejada · 24px'][i],craftList(c),['Boa para comparar vários horários. A área que recebe o toque ainda precisa ser fácil de alcançar.','Mantém horário e nome próximos, com separação clara entre itens.','Dá mais pausa a cada opção, mas exige mais rolagem.'][i])).join('');caption='Só muda o espaço interno acima e abaixo do conteúdo da linha (padding): 8, 16 ou 24 CSSpx. Conteúdo, fonte e alinhamento não mudam. Mais espaço não significa automaticamente melhor leitura.';
    } else if(['contraste-visual-legibilidade','cor-percepcao-paleta','cor-acessibilidade-verificacao'].includes(id)) {
      title=id==='cor-percepcao-paleta'?'Cada cor recebe um papel':'Contraste é uma relação entre duas cores';
      html=id==='cor-percepcao-paleta'?craftPanel('Estrutura e conteúdo',`<div class="craft-swatches"><div><i style="background:#fff;border:1px solid #7b7b7b"></i><span>Superfície · #FFFFFF</span></div><div><i style="background:#171717"></i><span>Texto · #171717</span></div><div><i style="background:#335cff"></i><span>Ação · #335CFF</span></div><div><i style="background:#9b1c31"></i><span>Erro + símbolo !</span></div></div>`,'As cores de fundo e texto ocupam mais área. A cor de ação concentra a atenção; erro precisa de informação além do vermelho.')+craftPanel('As funções na mesma ficha',craftCard(),'Azul não é usado no local, na data e em todas as bordas. O destaque fica reservado à ação.'):craftPanel('Evite · 2,52:1',`<div class="craft-contrast-low">Galeria Horizonte<br>Sábado, 24 out · 14h</div><p class="craft-readable-copy">Transcrição: Galeria Horizonte · Sábado, 24 out · 14h</p>`,'#A3A3A3 sobre #FFFFFF. Exemplo intencionalmente insuficiente para texto; a transcrição permanece legível.')+craftPanel('Prefira · 7,13:1',`<div class="craft-contrast-good">Galeria Horizonte<br>Sábado, 24 out · 14h</div><span class="craft-action">Salvar plano</span>`,'#525866 sobre #FFFFFF. A ação branca sobre #335CFF tem 5,10:1.');caption='A proporção compara a luminosidade do texto com a do fundo. Para texto comum, a norma de acessibilidade WCAG exige pelo menos 4,5:1 no nível AA. Com transparências ou imagens, é preciso conferir o contraste sobre o fundo que realmente aparece.';
    } else if(id.startsWith('typography-')) {
      title=id.includes('anatomy')?'Reconhecer a letra antes de escolher a fonte':id.includes('scale')?'A escala precisa aparecer no conteúdo':'O mesmo conteúdo precisa caber sem desaparecer';
      html=id.includes('anatomy')?craftPanel('Zoom · formas que confundem',`<div class="craft-type-zoom">Il1 <span>O0</span></div><p>Ilha 01 · Sala 10 · 14h</p><div class="craft-baseline">a e g <small>aberturas e espaços dentro das letras</small></div>`,'Observe a diferença entre I maiúsculo, l minúsculo, número 1, O e zero. Compare no tamanho de leitura, não apenas no zoom.')+craftPanel('Aplicação · leitura real',craftCard(),'Uma fonte precisa resolver nomes, números e horários no mesmo contexto.'):id.includes('scale')?craftPanel('Escala em uso',`<div class="craft-type-scale"><div><span>28/36 · título</span><strong>Uma tarde de arte</strong></div><div><span>20/28 · seção</span><h5>Visitas salvas</h5></div><div><span>16/24 · corpo</span><p>Reserve a tarde para explorar as exposições do Centro.</p></div><div><span>14/20 · apoio</span><small>Sábado, 24 out · 14h</small></div></div>`,'Os números mostram tamanho da letra / altura da linha, em pixels de referência da web (CSSpx). Cada estilo tem uma função.'):craftPanel('Coluna ampla',craftCard(),'Texto completo e altura livre.')+craftPanel('Coluna estreita · mesmo conteúdo',`<div class="craft-narrow">${craftCard()}</div>`,'A linha quebra; o título não é cortado nem reduzido para caber.');caption='Compare o título, o texto de leitura e as informações menores. Esses tamanhos são exemplos, não medidas obrigatórias para todos os produtos.';
    } else if(['elevacao-sombras','camadas-ordem-superficies','materiais-blur-translucidez','sheets-modais-dialogos'].includes(id)) {
      title=id==='elevacao-sombras'?'A sombra mostra o que está por cima':id==='materiais-blur-translucidez'?'Transparência não pode apagar o conteúdo':'O que deve aparecer por cima da tela?';
      html=id==='elevacao-sombras'?craftPanel('Evite · tudo flutua',`<div class="craft-shadow-heavy">${craftList()}</div>`,'Três sombras fortes tornam itens do mesmo nível concorrentes.')+craftPanel('Prefira · sombra no painel aberto',`<div class="craft-depth-base">${craftList()}<div class="craft-floating">Ordenar por horário ▾</div></div>`,'A lista fica na superfície; apenas o menu temporário se destaca.'):id==='materiais-blur-translucidez'?craftPanel('Evite · fundo interfere',`<div class="craft-material"><div class="craft-glass weak">Forma &amp; luz<br>24 out · 14h</div></div>`,'A textura compete com as letras. Desfocar o fundo (blur) não garante que o texto fique legível.')+craftPanel('Prefira · base de leitura',`<div class="craft-material"><div class="craft-glass">Forma &amp; luz<br>24 out · 14h</div></div>`,'Uma base quase opaca mantém a leitura estável sobre o fundo.'):craftPanel('Camadas separadas · o que fica por cima',`<ol class="craft-layers"><li><b>3 · Painel</b><span>Ordenar visitas<br>Horário · Distância</span></li><li><b>2 · Proteção do fundo</b><span>Separa o contexto temporariamente inativo.</span></li><li><b>1 · Superfície</b><span>Lista de visitas</span></li><li><b>0 · Fundo</b><span>Área contínua da tela</span></li></ol>`,'Leia de baixo para cima. Os números apenas indicam a ordem das camadas.');caption='O efeito visual deve explicar o que está sobre o quê. Uma sombra não define sozinha se a pessoa pode interagir com o fundo.';
    } else if(['alinhamento-optico','icones-peso-optico','kerning-tracking-curvas','pixels-densidades'].includes(id)) {
      title={'alinhamento-optico':'Centro da caixa não é centro percebido','icones-peso-optico':'Mesma caixa, massas visuais diferentes','kerning-tracking-curvas':'Ajuste local não é espaçar tudo','pixels-densidades':'Mesma dimensão lógica, mais amostras'}[id];
      if(id==='alinhamento-optico')html=craftPanel('Pela medida · centro da caixa',`<div class="craft-optical"><span class="craft-play"></span></div>`,'Pela medida, o triângulo está no centro. Mas a maior parte do desenho fica à esquerda, então ele parece deslocado.')+craftPanel('Ajustado a olho · 3px à direita',`<div class="craft-optical corrected"><span class="craft-play"></span></div>`,'A forma avança 3 CSSpx à direita. O círculo e o tamanho do triângulo não mudam.');
      if(id==='icones-peso-optico')html=craftPanel('Antes · mesmo tamanho',`<div class="craft-icon-row"><span class="craft-disc"></span><span class="craft-square"></span></div>`,'O quadrado preenche mais a caixa e parece mais pesado.')+craftPanel('Depois · tamanho ajustado',`<div class="craft-icon-row corrected"><span class="craft-disc"></span><span class="craft-square"></span></div>`,'Reduzir o quadrado mantém a família sem exigir dimensões idênticas.');
      if(id==='kerning-tracking-curvas')html=craftPanel('Kerning · espaço entre duas letras',`<div class="craft-kern">AV</div><div class="craft-kern corrected">AV</div>`,'Acima: distância original. Abaixo: V se aproxima de A; só o espaço do par muda.')+craftPanel('Curvas · espessura constante',`<div class="craft-radius"><div>Raio externo 24px<br>Recuo interno 8px<br>Raio interno 16px</div></div>`,'Neste exemplo, o canto externo tem raio de 24px. O recuo interno é de 8px, então o canto interno usa 16px. Isso mantém a faixa azul com espessura uniforme.');
      if(id==='pixels-densidades')html=[1,2,3].map(n=>craftPanel(`@${n}x · ${8*n} × ${8*n} amostras`,`<div class="craft-pixel-grid" style="--pixel:${24/n}px"><i></i></div>`,`Área de 8 × 8 unidades de layout, ampliada para mostrar os pixels. Mais pixels desenham a mesma área sem aumentar seu tamanho na tela.`)).join('');
      caption='As linhas-guia e ampliações ajudam a enxergar o ajuste. Elas não aparecem na interface final. Veja também o resultado no tamanho real: o ajuste deve melhorar o equilíbrio, sem desalinhar o restante.';
    } else if(['marca-legibilidade','ilustracao-coerencia','expressividade-contexto'].includes(id)) {
      title=id==='ilustracao-coerencia'?'O mesmo desenho em três tamanhos':id==='expressividade-contexto'?'A marca aparece sem atrapalhar o uso':'Duas marcas fictícias, a mesma estrutura';
      html=id==='expressividade-contexto'?[['Alta · descoberta','<div class="craft-art" style="--art-size:112px"><i></i><b></b></div>','A imagem apresenta o clima da visita antes dos dados.'],['Média · detalhe','<p class="craft-brand-signature">rota ●</p>','O nome da marca continua presente, mas ocupa menos espaço que o conteúdo.'],['Baixa · revisão','','Antes de concluir, os dados e a ação têm prioridade sobre a expressão.']].map(([label,brand,note])=>craftPanel(label,brand+craftCard(),note)).join(''):id==='ilustracao-coerencia'?[32,64,112].map(n=>craftPanel(`${n}px · mesmas formas`,`<div class="craft-art" style="--art-size:${n}px"><i></i><b></b></div>`,'Arco, círculo e mesma proporção. O detalhe não se multiplica na versão pequena.')).join(''):craftPanel('Rota · direta e urbana',`<div class="craft-brand rota"><b>rota ●</b>${craftCard()}</div>`,'Azul, letras sem prolongamentos nas pontas (sem serifa) e cantos pouco arredondados.')+craftPanel('Viva · editorial e acolhedora',`<div class="craft-brand viva"><b>viva ◒</b>${craftCard()}</div>`,'Vinho, título com prolongamentos nas pontas das letras (com serifa) e cantos mais arredondados. Os dados e a ação continuam na mesma ordem.');caption=id==='ilustracao-coerencia'?'Os três tamanhos mantêm o arco, o círculo e a proporção entre eles. Na menor versão, poucos elementos mantêm o reconhecimento; não comprima uma ilustração cheia de detalhes.':id==='expressividade-contexto'?'Os mesmos dados permanecem nas três versões. A marca ocupa menos espaço quando a pessoa passa da descoberta para a revisão; a cor da ação e a hierarquia do conteúdo continuam estáveis. Não é preciso inserir uma ilustração em todos os momentos.':'Observe a mudança de aparência: as duas marcas mostram Forma & luz, o mesmo local, a mesma data e a mesma ação. Identidade altera a linguagem visual, não a informação necessária.';
    } else if(id==='estados-interface'||id==='projeto-prototipo-estados'||id==='navegacao-tabs-back-home'||id==='mapa-estrutura-fluxo') {
      const states=id==='estados-interface'||id==='projeto-prototipo-estados';title=states?'A mesma visita em três momentos':'Abrir, consultar, voltar ao mesmo lugar';
      html=(states?[['1 · Antes de salvar','Forma &amp; luz','24 out · 14h','Salvar plano','O nome e a data deixam claro qual visita será salva.'],['2 · Durante a tentativa','Forma &amp; luz','24 out · 14h','Salvando…','O espaço da ação permanece; o conteúdo não salta.'],['3 · Resultado confirmado','Forma &amp; luz','24 out · 14h','✓ Plano salvo','Texto e símbolo distinguem o estado, não apenas a cor.']]:[['1 · Lista','Visitas no Centro','Forma &amp; luz · 14h','Abrir detalhe','A pessoa começa pela lista de visitas.'],['2 · Detalhe','Forma &amp; luz','Galeria Horizonte · 14h','← Voltar à lista','O título preserva a identidade do item.'],['3 · Retorno','Visitas no Centro','Forma &amp; luz · 14h','Mesma posição','A seleção continua reconhecível na lista.']]).map(([label,name,date,action,note])=>craftPanel(label,`<div class="craft-sequence"><small>ROTA · TELA DE EXEMPLO</small><strong>${name}</strong><p>${date}</p><span class="craft-action">${action}</span></div>`,note)).join('');caption='Leia da esquerda para a direita, ou de cima para baixo no celular. São etapas da mesma ação, não três opções de organização da tela. Os controles ilustrados não executam ações.';
    }
    if(!html)return '';
    return `<figure class="craft-figure"><h3>${title}</h3><div class="craft-comparison">${html}</div><figcaption>${caption}</figcaption></figure>`;
  }
  function renderExample(e) {
    if(e.visualHtml) return `<section class="example-card original-example"><span class="example-source">EXEMPLO ORIGINAL · ROTA</span><h3>${esc(e.title)}</h3>${e.scenario?`<div class="example-scenario"><strong>O que a pessoa quer fazer</strong>${esc(e.scenario)}</div>`:""}${e.comparisonFocus?`<p class="example-controls">${esc(e.comparisonFocus)}</p>`:""}<p class="demo-description">Tela de exemplo. Os botões desenhados não fazem reservas nem enviam dados.</p><figure class="demo-figure"><div class="demo-stage" role="group" aria-label="${esc(e.alt||e.title)}">${e.visualHtml}</div><figcaption class="demo-caption">${esc(e.comparisonFocus||e.scenario||"Observe a relação entre o conteúdo, os agrupamentos e a ação principal nesta composição.")} Aplicativo e dados fictícios. Referência de acabamento: <a href="https://alignui.com/docs/v1.2/introduction" target="_blank" rel="noopener noreferrer">AlignUI Base Components v1.2</a>. As telas foram criadas para este material; não são modelos oficiais.</figcaption></figure><div class="example-analysis">${e.analysis}</div></section>`;
    let image='';
    if(e.image) image=`<figure><a class="image-source-link" href="${esc(e.image)}" target="_blank" rel="noopener noreferrer" aria-label="Abrir imagem em tamanho original: ${esc(e.title)}"><div class="example-image-frame" ${e.visualAspect?`style="aspect-ratio:${esc(e.visualAspect)}"`:""}><img src="${esc(e.image)}" alt="${esc(e.alt||e.title)}" loading="lazy" decoding="async"></div></a><figcaption>${esc(e.credit||e.source)}${e.license?` · ${esc(e.license)}`:''}${e.licenseUrl?` · <a href="${esc(e.licenseUrl)}" target="_blank" rel="noopener noreferrer">Licença</a>`:''}${e.url?`<br><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Fonte da imagem e contexto</a>`:''}</figcaption></figure>`;
    return `<section class="example-card"><span class="example-source">${esc(e.source)}</span><h3>${esc(e.title)}</h3>${image}${e.versionNote?`<p class="example-version"><strong>Contexto e atualidade.</strong> ${esc(e.versionNote)}${e.versionUrl?` <a href="${esc(e.versionUrl)}" target="_blank" rel="noopener noreferrer">Ver histórico da fonte</a>`:''}</p>`:''}<div class="example-analysis">${e.analysis}</div>${e.url?`<a class="example-link" href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Examinar o exemplo original ${external}<span class="sr-only"> (abre em nova aba)</span></a>`:''}${!e.image&&e.url?'<p class="link-only">Referência real com análise autoral. A imagem não é reproduzida aqui; abra o original para observar o exemplo no contexto.</p>':''}</section>`;
  }
  function renderTeachingExamples(l) {
    const focused=craftFigure(l);
    if(!focused)return l.examples.map(renderExample).join('');
    const contexts=l.examples.filter(e=>e.visualHtml?.includes('rx-study'));
    const context=contexts.length?`<details class="craft-context"><summary>Ver a aplicação completa no Rota</summary>${contexts.map(renderExample).join('')}</details>`:'';
    const commentary=l.examples.filter(e=>!e.visualHtml?.includes('rx-study')&&!e.visualHtml?.includes('craft-example')).map(e=>e.analysis?`<div class="example-analysis">${e.analysis}</div>`:'').join('');
    return focused+commentary+context;
  }
  function renderLesson(l) {
    const index=lessons.findIndex(x=>x.id===l.id), prev=lessons[index-1],next=lessons[index+1];
    const examples=`<section class="inline-examples" id="${esc(l.id)}--examples" aria-label="Exemplos aplicados"><h2 class="rail-heading">Exemplo explicado</h2>${renderTeachingExamples(l)}</section>`;
    const after=l.sections.length-1;
    return `<header class="lesson-header"><div class="breadcrumb"><a href="#inicio">Trilha</a><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg><span>${String(l.moduleIndex+1).padStart(2,'0')} · ${esc(l.module.title)}</span></div><h1>${esc(l.title)}</h1><p class="intro">${esc(l.summary)}</p><div class="lesson-meta"><span class="read-label">Lição ${index+1} de ${lessons.length} · ${l.minutes||12} min de leitura</span><span>Leitura no seu ritmo</span>${markButton(l.id)}</div></header><div class="lesson-grid"><article class="lesson-prose" aria-label="Conteúdo completo da lição"><details class="lesson-module-contract"><summary>O roteiro deste bloco: ${esc(l.module.title)}</summary>${moduleContract(l.module)}</details><section class="objectives"><h2>O assunto desta lição</h2><ul>${l.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><nav class="lesson-toc" aria-label="Nesta lição"><span class="eyebrow">Nesta lição</span><ul>${l.sections.map((s,i)=>`<li><a href="#${esc(l.id)}--s${i}" data-section="${i}">${esc(s.title)}</a></li>${i===after?`<li><a href="#${esc(l.id)}--examples" data-section="examples">Exemplos aplicados</a></li>`:''}`).join('')}<li><a href="#${esc(l.id)}--sources" data-section="sources">Referências para saber mais</a></li></ul></nav>${l.sections.map((s,i)=>`<section class="lesson-section" id="${esc(l.id)}--s${i}"><h2>${esc(s.title)}</h2>${s.body}</section>${i===after?examples:''}`).join('')}<section class="sources" id="${esc(l.id)}--sources"><h2>Referências para saber mais</h2><ul class="source-list">${l.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}<span class="sr-only"> (abre em nova aba)</span></a>${s.note?`<small>${esc(s.note)}</small>`:''}</li>`).join('')}</ul>${l.books?.length?`<h3>Leitura nos livros</h3><p class="book-method">Estas referências ajudaram a preparar a lição. As páginas são contadas desde o início do PDF e podem ter números diferentes no livro impresso. A explicação foi escrita para este material; não reproduz as páginas do livro.</p><ul class="book-list">${l.books.map(renderBook).join('')}</ul>`:''}${l.videos?.length?`<h3>Assista com um objetivo</h3>${l.videos.map(v=>`<a class="video-card" href="${esc(v.url)}" target="_blank" rel="noopener noreferrer"><strong>${esc(v.title)} ${external}</strong><span>${esc(v.source)} · ${esc(v.note||'Vídeo oficial em inglês. Use as legendas quando disponíveis.')}</span><span class="sr-only">Abre em nova aba.</span></a>`).join('')}`:''}</section><section class="completion-box"><h2>Terminou a leitura?</h2><p>Use a marcação para lembrar onde parou. Você pode voltar a esta lição quando precisar.</p>${markButton(l.id)}<nav class="lesson-pagination" aria-label="Continuar a trilha">${prev?`<a href="#${esc(prev.id)}"><small>Anterior</small>${esc(prev.title)}</a>`:'<a href="#inicio"><small>Voltar</small>Visão geral da trilha</a>'}${next?`<a href="#${esc(next.id)}"><small>Próxima lição</small>${esc(next.title)}</a>`:'<a href="#progresso"><small>Revisar</small>Meu progresso e próximos estudos</a>'}</nav></section></article></div>${footer()}`;
  }
  function renderLibrary() {
    const seen=new Set();
    const groups=course.modules.map(m=>({title:m.title,sources:m.lessons.flatMap(l=>l.sources).filter(s=>{if(seen.has(s.url))return false;seen.add(s.url);return true;})}));
    const videos=[...new Map(lessons.flatMap(l=>l.videos||[]).map(v=>[v.url,v])).values()];
    const bookMap=new Map();lessons.forEach(l=>(l.books||[]).forEach(b=>{const key=b.title+'|'+b.authors;if(!bookMap.has(key))bookMap.set(key,{...b,lessons:[]});bookMap.get(key).lessons.push({id:l.id,title:l.title});}));const books=[...bookMap.values()];
    return `<div class="resource-page"><span class="eyebrow">Biblioteca de estudo</span><h1>Referências para saber mais.</h1><p class="intro">Esta página reúne as referências das lições. A leitura é opcional. Os guias indicam quando uma orientação vale para sites, iPhone ou Android.</p><div class="note"><p><strong>Como ler as fontes:</strong> guias oficiais mostram padrões de cada plataforma. Normas de acessibilidade explicam requisitos, como o contraste mínimo do texto. Livros e artigos ajudam a entender as decisões. Nem toda recomendação serve da mesma forma para qualquer interface.</p><p><strong>Referência visual e atualidade:</strong> os exemplos Rota são composições originais, criadas para esta trilha em outubro de 2026. Sua linguagem visual foi informada pela documentação pública <a href="https://alignui.com/docs/v1.2/introduction" target="_blank" rel="noopener noreferrer">AlignUI v1.2</a>. Use a fonte para observar relações de tipografia, cor, espaço e superfície, não para copiar uma solução fora de contexto.</p><p>Os exemplos não reproduzem o kit PRO. A interface externa deste curso mantém a linguagem de leitura em branco, preto, cinzas e azul. Referências de Apple, Android, W3C, GOV.UK e outros autores permanecem na bibliografia para comparação de contexto, convenções e evidência. Data de consulta não é data de lançamento; uma fonte recente também não prova que uma solução serve ao seu projeto.</p><p>Os textos das lições são autorais. Livros e publicações protegidas são indicados por links, sem reprodução de capítulos. Páginas, recomendações e interfaces externas podem mudar.</p></div>${groups.map(g=>`<section class="bibliography-group"><h2>${esc(g.title)}</h2><ul>${g.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>${s.note?`<small>${esc(s.note)}</small>`:''}</li>`).join('')}</ul></section>`).join('')}${books.length?`<section class="bibliography-group"><h2>Livros e leitura dirigida</h2><p class="book-method">Os trechos selecionados ajudaram a preparar as explicações. Os livros não foram lidos integralmente. As lições informam as páginas físicas dos exemplares consultados, com as incertezas de edição preservadas. Nenhum PDF, capítulo ou ilustração protegida é distribuído aqui.</p><ul class="book-list">${books.map(b=>`<li><cite>${esc(b.title)}</cite><span>${esc(b.authors)}${b.edition?` · ${esc(b.edition)}`:''}</span><small>Aplicado em: ${b.lessons.map(l=>`<a href="#${esc(l.id)}">${esc(l.title)}</a>`).join('; ')}.</small></li>`).join('')}</ul></section>`:''}<section class="bibliography-group"><h2>Vídeos e sessões oficiais</h2><p class="intro">Assista depois da leitura. Pause para observar como o conceito aparece na tela. Em geral, o áudio original é em inglês.</p>${videos.map(v=>`<a class="video-card" href="${esc(v.url)}" target="_blank" rel="noopener noreferrer"><strong>${esc(v.title)} ${external}</strong><span>${esc(v.source)} · ${esc(v.note||'Referência complementar.')}</span></a>`).join('')}</section>${footer()}</div>`;
  }
  const glossary=[['Affordance','Possibilidade de ação oferecida por um objeto. Na interface, o sinal que comunica essa possibilidade é um significante: aparência, rótulo, posição ou outro indício.'],['App bar / header','Barra do aplicativo ou cabeçalho. Apresenta contexto, título e ações pertinentes à tela; não deve reunir todas as funções do produto.'],['Back / Up','Voltar e subir na hierarquia. Voltar geralmente percorre o histórico; subir leva ao nível pai. O comportamento depende da plataforma e do fluxo.'],['Bottom sheet','Painel que entra pela borda inferior. Pode ser modal ou não modal. Altura, rolagem, teclado e forma de fechar precisam ser planejados.'],['Card','Cartão de conteúdo: um contêiner que reúne informações de uma entidade ou tarefa. É útil quando o agrupamento facilita comparar ou agir.'],['CSS px, pt, dp e sp','Unidades diferentes. CSS px é uma unidade de referência na web; pt é usado no layout Apple; dp trata densidade no Android; sp acrescenta escalonamento de texto. Não iguale números automaticamente.'],['Design system','Sistema de design. Conjunto mantido de princípios, padrões, componentes, tokens, documentação e governança. Uma biblioteca visual isolada não cobre tudo isso.'],['Drawer / sidebar','Gaveta de navegação e barra lateral. A gaveta se abre temporariamente; a barra lateral pode permanecer visível em telas maiores.'],['Edge-to-edge','Conteúdo de borda a borda, inclusive por trás de barras do sistema. Exige tratamento dos recuos do sistema para proteger texto e ações.'],['Empty state','Estado vazio. Explica por que não há conteúdo, o que isso significa e qual ação faz sentido, sem inventar um erro.'],['Feedback','Resposta perceptível do sistema a uma ação ou mudança. Deve indicar o que aconteceu e, quando necessário, o que fazer em seguida.'],['Flow','Fluxo: sequência de passos, decisões e estados para realizar uma tarefa. Inclui caminhos alternativos, cancelamento e falhas.'],['Grid','Grade: estrutura de alinhamentos, colunas e espaçamentos que ajuda a organizar a composição. Não é a arquitetura da informação.'],['Heurística','Orientação ampla para investigar problemas de usabilidade. Ajuda a formular uma crítica; não prova sozinha que um problema acontece ou que uma solução funciona.'],['Home','Pode ser a tela inicial do aplicativo ou uma ação do sistema operacional. São coisas diferentes: um app não deve imitar indevidamente o controle de início do sistema.'],['Insets / safe area','Recuos de proteção e área segura. Ajudam a proteger conteúdo de barras, recortes e regiões de gestos do sistema. O teclado exige tratamento específico, que varia por plataforma e framework; não suponha que a área segura já resolva sua sobreposição. Os valores mudam conforme o contexto.'],['Line height / leading','Altura de linha ou entrelinha: distância vertical entre linhas de texto. Precisa ser ajustada em conjunto com tamanho, largura de coluna e fonte.'],['Modal','Apresentação que exige encerrar uma interação antes de voltar ao contexto anterior. Pode aparecer como diálogo, folha ou tela; forma visual e comportamento modal não são sinônimos.'],['Onboarding','Introdução ao uso de um produto. Deve ajudar a realizar a primeira tarefa relevante, sem transformar instruções em uma barreira obrigatória.'],['Progressive disclosure','Divulgação progressiva: mostrar detalhes quando eles se tornam necessários. Não justifica esconder instruções essenciais nem conteúdo de estudo solicitado integralmente.'],['Prototype','Protótipo: representação feita para investigar uma pergunta. Pode ter baixa ou alta fidelidade; aparência realista não significa funcionamento completo.'],['Responsive / adaptive','Responsivo e adaptativo. São estratégias para reorganizar o layout diante de espaço, dispositivo e contexto; os termos variam entre sistemas e não equivalem a encolher uma tela.'],['Skeleton','Estrutura provisória exibida durante o carregamento. Sugere a organização do conteúdo, mas não deve fingir informação disponível nem substituir uma mensagem útil.'],['Splash screen','No Android, SplashScreen é a superfície de lançamento do sistema. A Apple distingue a launch screen, usada na transição de inicialização, de uma splash de marca exibida depois dela. Não trate esses termos como equivalentes nem prolongue a espera artificialmente.'],['Tab bar / navigation bar','Barra de abas ou de navegação. Oferece acesso a destinos principais de mesmo nível. O nome e os comportamentos específicos variam por plataforma.'],['Token','Nome semântico para uma decisão reutilizável, como cor de ação, espaço ou estilo de texto. Permite mudar o sistema com consistência.'],['Touch target','Área de toque que recebe a interação. Pode ser maior que o desenho visível do ícone. Dimensões recomendadas e unidades dependem da plataforma.'],['Usability testing','Teste de usabilidade: observar participantes tentando realizar tarefas representativas. Evidencia problemas daquele contexto; não é votação de preferências visuais.'],['Wireframe','Esboço estrutural de uma interface. Ajuda a discutir conteúdo, prioridade, fluxo e agrupamento antes do acabamento visual.']];
  function renderGlossary(){return `<div class="resource-page"><span class="eyebrow">Vocabulário de trabalho</span><h1>Termos, sem mistério.</h1><p class="intro">Os termos em inglês aparecem nas referências de interface. Use estas traduções como ponto de partida e volte às lições para entender as decisões.</p><dl class="glossary">${(course.glossary?.length?course.glossary.map(g=>[g.term,g.definition]):glossary.filter(([term])=>!['Design system','Token','Feedback','Usability testing'].includes(term))).map(([term,text])=>`<div class="glossary-item"><dt>${esc(term)}</dt><dd>${esc(text)}</dd></div>`).join('')}</dl>${footer()}</div>`;}
  function renderProgress(){return `<div class="resource-page"><span class="eyebrow">Seu estudo</span><h1>Acompanhe sua leitura.</h1><p class="intro">O progresso acompanha as lições que você marcou como estudadas. Use as marcações para acompanhar sua leitura.</p><div class="progress-summary"><div class="big-number">${pct(state.completed.length,lessons.length)}%</div><p class="privacy-note">${state.completed.length} de ${lessons.length} lições estudadas.</p>${course.modules.map(m=>{const n=m.lessons.filter(l=>done(l.id)).length;return `<div class="progress-module"><div class="progress-module-head"><a href="#${esc(m.lessons[0].id)}">${esc(m.title)}</a><span>${n}/${m.lessons.length} · ${pct(n,m.lessons.length)}%</span></div><div class="progress-track" aria-hidden="true"><span style="width:${pct(n,m.lessons.length)}%"></span></div></div>`;}).join('')}</div>${state.archived.completed.length?`<div class="note"><strong>Histórico preservado</strong><p>${state.archived.completed.length} lições da edição anterior foram retiradas do roteiro. As marcações e posições continuam na sua exportação, sem concluir automaticamente outra lição.</p></div>`:''}<div class="note"><strong>Seu navegador guarda o progresso.</strong><p>As marcações e a última posição de leitura ficam no localStorage, o armazenamento local deste site no navegador. Não usamos IP para identificar você, não há conta nem sincronização entre dispositivos. Limpar os dados do site, usar outro navegador ou encerrar uma sessão privada pode apagar o progresso.</p></div><section class="progress-controls"><h2>Uma cópia para levar com você</h2><p class="intro">Exporte um arquivo JSON para guardar ou transferir a outro navegador. Ao importar, as lições estudadas são somadas às marcações atuais; nenhuma marcação é removida.</p><div class="button-row"><button class="button primary" id="export-progress">Exportar progresso</button><button class="button" id="import-progress">Importar arquivo JSON</button><button class="button danger" id="reset-progress">Limpar marcações locais</button></div><input type="file" id="progress-file" accept="application/json,.json" hidden><div id="import-status" class="import-status" role="status">${esc(importMessage)}</div><p class="privacy-note">O arquivo contém apenas identificadores das lições, posição de leitura e data da exportação. A importação é processada no seu navegador, sem enviar o arquivo a um servidor.</p></section>${footer()}</div>`;}
  function syncNavAccessibility(){const sidebar=document.querySelector('#sidebar');const closed=innerWidth<=800&&!document.body.classList.contains('nav-open');sidebar.inert=closed;sidebar.setAttribute('aria-hidden',String(closed));}
  function closeNav(returnFocus=false){document.querySelector('#sidebar').classList.remove('open');document.querySelector('.nav-backdrop').hidden=true;document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');document.body.classList.remove('nav-open');syncNavAccessibility();if(returnFocus)document.querySelector('.menu-toggle').focus();}
  function openNav(){document.querySelector('#sidebar').classList.add('open');document.querySelector('.nav-backdrop').hidden=false;document.querySelector('.menu-toggle').setAttribute('aria-expanded','true');document.body.classList.add('nav-open');syncNavAccessibility();document.querySelector('#course-search').focus();}
  function savePosition(){if(byId.has(activeRoute)){state.positions[activeRoute]=window.scrollY;persist();}}
  function mountComponentControls(study,column) {
    const mode=study?.dataset.demoControl;
    if(!mode)return;
    const panel=document.createElement('div');panel.className='rx-controls';
    const makeGroup=(label,choices,onChange)=>{
      const group=document.createElement('fieldset');group.className='rx-control-group';
      const legend=document.createElement('legend');legend.textContent=label;group.appendChild(legend);
      const options=document.createElement('div');options.className='rx-control-options';
      choices.forEach(([text,value],index)=>{
        const button=document.createElement('button');button.type='button';button.className='rx-control-option';button.textContent=text;button.setAttribute('aria-pressed',String(index===0));
        button.addEventListener('click',()=>{options.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));onChange(value);});
        options.appendChild(button);
      });
      group.appendChild(options);panel.appendChild(group);
    };
    if(mode.includes('width'))makeGroup('Largura do componente',[['340 CSSpx','340px'],['260 CSSpx','260px']],value=>study.style.setProperty('--rx-component-width',value));
    if(mode.includes('type'))makeGroup('Texto do componente',[['100%','1'],['130%','1.3']],value=>study.style.setProperty('--rx-type-scale',value));
    if(mode==='grid'){
      makeGroup('Sobreposição de grade',[['Visível','visible'],['Oculta','hidden']],value=>study.classList.toggle('rx-grid-hidden',value==='hidden'));
      const rulers=document.createElement('div');rulers.className='rx-rulers';rulers.setAttribute('aria-label','Amostras locais de espaçamento de8,16 e24 CSSpx.');
      rulers.innerHTML='<span><i></i>8px</span><span><i></i>16px</span><span><i></i>24px</span>';panel.appendChild(rulers);
    }
    const caption=document.createElement('p');caption.className='rx-control-caption';caption.textContent=mode==='grid'?'Colunas e espaçamento são medidas diferentes.':'Este controle altera o componente; ampliar a moldura é outra função.';panel.appendChild(caption);
    column.insertBefore(panel,column.firstChild);
  }

  const anatomyTargets={
    'ux-ui-problema-objetivos':['.rx-content h2','.rx-total','.rx-primary'],
    'gestalt-agrupamento':['.rx-field','.rx-field:nth-of-type(2)','.rx-field-label'],
    'consistencia-ritmo':['.rx-list-item','.rx-list-item:nth-of-type(2)','.rx-list-item:nth-of-type(3)'],
    'icones-imagens-significado':['.rx-art','.rx-location','.rx-primary'],
    'navegacao-encontrabilidade':['.rx-search','.rx-chips','.rx-list-item'],
    'safe-areas-insets-edge-to-edge':['.rx-status','.rx-content','.rx-home'],
    'header-top-app-bar':['.rx-appbar','.rx-content h2','.rx-footer'],
    'navegacao-tabs-back-home':['.rx-tabs','.rx-tab','.rx-active'],
    'menus-sidebar-drawer':['.rx-menu-item','.rx-menu-selected','.rx-drawer'],
    'teclado-toque-gestos':['.rx-input','.rx-keyboard-action','.rx-keyboard'],
    'home-dashboard':['.rx-content h2','.rx-primary','.rx-plan-card'],
    'tela-detalhe':['.rx-content h2','.rx-content .rx-box','.rx-primary'],
    'busca-filtros':['.rx-search','.rx-sort','.rx-chips'],
    'formularios':['.rx-field-label','.rx-field-help','.rx-primary'],
    'estados-interface':['.rx-error-banner','.rx-box','.rx-primary'],
    'sheets-modais-dialogos':['.rx-scrim','.rx-sheet','.rx-sheet .rx-primary'],
    'cor-percepcao-paleta':['.rx-content','.rx-chip-active','.rx-primary'],
    'cor-acessibilidade-verificacao':['.rx-pair','.rx-measured-copy','.rx-primary']
  };
  function mountAnatomy(root) {
    const selectors=anatomyTargets[activeRoute]||[];
    root.querySelectorAll('.rx-study').forEach((study,studyIndex)=>{
      const notes=[...study.querySelectorAll('.rx-notes ol>li')];
      selectors.forEach((selector,index)=>{
        const target=study.querySelector('.rx-phone '+selector),note=notes[index];
        if(!target||!note)return;
        const title=note.querySelector('h4')?.textContent||'Região anotada';
        const targetId=`${activeRoute}-figure-${studyIndex}-target-${index}`;
        target.id=targetId;target.classList.add('rx-annotated');target.dataset.callout=String(index+1);
        target.setAttribute('aria-label',`${index+1}. ${title}`);
        const number=note.querySelector('.rx-note-number');
        if(number){const link=document.createElement('button');link.type='button';link.className='rx-callout-link';link.textContent=String(index+1);link.setAttribute('aria-label',`Localizar na figura: ${title}`);link.setAttribute('aria-controls',targetId);link.addEventListener('click',()=>{study.querySelectorAll('.rx-callout-active').forEach(el=>el.classList.remove('rx-callout-active'));target.classList.add('rx-callout-active');target.scrollIntoView({block:'nearest',inline:'nearest'});});number.replaceWith(link);}
      });
      // Unlinked observations remain prose, never misleading numbered callouts.
      study.querySelectorAll('.rx-note-number').forEach(number=>number.remove());
    });
  }
  let exampleObserver;
  let exampleResize;
  function mountRealisticExamples(root=document) {
    if (exampleObserver) exampleObserver.disconnect();
    if (exampleResize) window.removeEventListener('resize', exampleResize);
    const slots=[...root.querySelectorAll('.rx-device-slot')];
    const fit=slot=>{
      const pan=slot.parentElement;
      const expanded=pan.classList.contains('rx-expanded');
      const naturalScale=Math.min(1,pan.clientWidth/390);
      const scale=expanded?1:naturalScale;
      slot.style.setProperty('--rx-scale',String(scale));
      slot.style.height=(844*scale)+'px';
      slot._zoom.hidden=naturalScale>=1&&!expanded;
      slot._hint.hidden=!(expanded&&naturalScale<1);
    };
    slots.forEach((slot,i)=>{
      const column=slot.parentElement;
      const pan=document.createElement('div');pan.className='rx-pan';
      column.insertBefore(pan,slot);pan.appendChild(slot);
      const button=document.createElement('button');
      button.className='rx-zoom';button.type='button';button.textContent='Ampliar tela';
      button.setAttribute('aria-pressed','false');
      slot.id='rx-viewport-'+i;button.setAttribute('aria-controls',slot.id);
      const hint=document.createElement('p');hint.className='rx-pan-hint';hint.hidden=true;
      hint.textContent='Tela ampliada. Deslize na horizontal para ver as laterais.';
      button.addEventListener('click',()=>{
        const expanded=pan.classList.toggle('rx-expanded');
        button.setAttribute('aria-pressed',String(expanded));
        button.textContent=expanded?'Ajustar à largura':'Ampliar tela';
        if(!expanded)pan.scrollLeft=0;
        fit(slot);
      });
      column.insertBefore(button,pan);column.insertBefore(hint,pan);
      slot._zoom=button;slot._hint=hint;fit(slot);
      mountComponentControls(column.closest('.rx-study'),column);
    });
    exampleResize=()=>slots.forEach(fit);
    if ('ResizeObserver' in window) {
      exampleObserver=new ResizeObserver(exampleResize);
      slots.forEach(slot=>exampleObserver.observe(slot.parentElement));
    } else window.addEventListener('resize',exampleResize);
  }

  function renderRoute({initial=false}={}) {
    let hash;try{hash=decodeURIComponent(location.hash.slice(1)||'inicio');}catch(e){hash='inicio';}const [rawRoute,section]=hash.split('--');const route=byId.has(rawRoute)?rawRoute:(legacyRoutes[rawRoute]||rawRoute);
    activeRoute=byId.has(route)||['inicio','biblioteca','glossario','progresso'].includes(route)?route:'inicio';
    closeNav();
    if(byId.has(activeRoute)){const l=byId.get(activeRoute);state.lastLesson=l.id;persist();main.innerHTML=renderLesson(l);document.title=`${l.title} — Fundamentos de UI`;}
    else {main.innerHTML=activeRoute==='biblioteca'?renderLibrary():activeRoute==='glossario'?renderGlossary():activeRoute==='progresso'?renderProgress():renderOverview();document.title=(activeRoute==='inicio'?'Fundamentos de UI para iniciantes':activeRoute==='biblioteca'?'Biblioteca':activeRoute==='glossario'?'Glossário':'Meu progresso')+' — Fundamentos de UI';}
    main.querySelectorAll('table').forEach(t=>{const wrap=document.createElement('div');wrap.className='lesson-table';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Tabela com rolagem horizontal');t.before(wrap);wrap.append(t);});
    main.querySelectorAll('.example-card img').forEach(img=>img.addEventListener('error',()=>{const fig=img.closest('figure');const note=document.createElement('p');note.className='link-only';note.textContent='A imagem não pôde ser carregada. Use o link do exemplo original para consultá-la.';fig.replaceWith(note);},{once:true}));
    mountRealisticExamples(main);
    mountAnatomy(main);
    updateProgress();
    if(!initial) main.focus({preventScroll:true});
    requestAnimationFrame(()=>{if(section){document.getElementById(activeRoute+'--'+section)?.scrollIntoView({behavior:'instant',block:'start'});}else window.scrollTo({top:(initial||resumeRequested)&&byId.has(activeRoute)?state.positions[activeRoute]||0:0,behavior:'instant'});resumeRequested=false;});
  }
  document.querySelector('#course-search').addEventListener('input',e=>renderNav(e.target.value));
  document.querySelector('.menu-toggle').addEventListener('click',()=>document.body.classList.contains('nav-open')?closeNav(true):openNav());
  document.querySelector('.menu-close').addEventListener('click',()=>closeNav(true));
  document.querySelector('.nav-backdrop').addEventListener('click',()=>closeNav(true));
  document.addEventListener('keydown',e=>{if(!document.body.classList.contains('nav-open'))return;if(e.key==='Escape'){e.preventDefault();closeNav(true);}if(e.key==='Tab'){const els=[...document.querySelector('#sidebar').querySelectorAll('a[href],button,input')].filter(x=>x.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
  document.addEventListener('click',async e=>{
    const motion=e.target.closest('[data-motion-toggle]');
    if(motion){const demo=motion.closest('.motion-demo');const playing=demo.classList.toggle('is-playing');motion.textContent=playing?'Pausar movimento':'Reproduzir movimento';demo.querySelector('.motion-status').textContent=playing?'Em movimento. Compare os pontos que compartilham direção e tempo.':'Pausado. A imagem parada não demonstra movimento conjunto.';return;}
    const mark=e.target.closest('[data-complete]');
    if(mark){const id=mark.dataset.complete;if(done(id))state.completed=state.completed.filter(x=>x!==id);else state.completed.push(id);persist();updateProgress();document.querySelector('#announcement').textContent=done(id)?(storageWorks?'Lição marcada como estudada. Progresso salvo neste navegador.':'Lição marcada nesta sessão. O navegador não permitiu salvar; exporte para preservar.'):'Marcação removida.';return;}
    const sectionLink=e.target.closest('[data-section]');
    if(sectionLink){e.preventDefault();document.getElementById(activeRoute+'--'+(sectionLink.dataset.section.match(/^\d+$/)?'s':'')+sectionLink.dataset.section)?.scrollIntoView();return;}
    const anchor=e.target.closest('a[href^="#"]');
    if(anchor && !anchor.classList.contains('skip-link')) {savePosition();resumeRequested=anchor.hasAttribute('data-resume')||anchor.id==='continue-top';closeNav();if(anchor.hash===location.hash){e.preventDefault();renderRoute();}return;}
    if(e.target.closest('#export-progress')){savePosition();const blob=new Blob([JSON.stringify({schemaVersion:2,course:'ui-mobile',exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`ui-mobile-progresso-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#import-status').textContent='Arquivo de progresso preparado para download.';}
    if(e.target.closest('#import-progress'))document.querySelector('#progress-file').click();
    if(e.target.closest('#reset-progress') && confirm('Limpar todas as marcações e posições de leitura deste navegador? Exporte uma cópia primeiro se quiser guardar seu progresso.')){state.completed=[];state.positions={};state.lastLesson=null;state.archived={completed:[],positions:{},lastLesson:null};persist();importMessage='Marcações e posições locais foram limpas.';renderRoute();}
  });
  document.addEventListener('change',async e=>{if(e.target.id!=='progress-file')return;const file=e.target.files[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('O arquivo é muito grande. Use um JSON de progresso exportado por esta trilha.');const data=cleanState(JSON.parse(await file.text()));state.completed=[...new Set([...state.completed,...data.completed])];if(data.lastLesson)state.lastLesson=data.lastLesson;state.positions={...state.positions,...data.positions};state.archived={completed:[...new Set([...state.archived.completed,...data.archived.completed])],positions:{...state.archived.positions,...data.archived.positions},lastLesson:data.archived.lastLesson||state.archived.lastLesson};persist();importMessage=`Progresso importado: ${state.completed.length} ${state.completed.length===1?'lição estudada':'lições estudadas'} no total. Suas marcações anteriores foram preservadas.`;renderRoute();}catch(err){document.querySelector('#import-status').textContent='Não foi possível importar. '+(err instanceof SyntaxError?'O arquivo não é um JSON válido.':err.message);}e.target.value='';});
  window.addEventListener('hashchange',()=>renderRoute());
  window.addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(savePosition,350);},{passive:true});
  window.addEventListener('beforeunload',savePosition);
  document.addEventListener('visibilitychange',()=>{if(document.hidden)savePosition();});
  window.addEventListener('resize',()=>{if(innerWidth>800)closeNav();else syncNavAccessibility();});
  renderRoute({initial:true});
})();
